cat > /tmp/sweep.js <<'EOF'
const {spawnSync} = require('child_process');
const EXE = '/workspace/dataset/test15_executable';
function hex(cp){return 'U+'+cp.toString(16).toUpperCase().padStart(4,'0');}
const cps = [];
for (let c=1;c<=0xFF;c++) cps.push(c);
cps.push(0x1680);
for (let c=0x2000;c<=0x206F;c++) cps.push(c);
cps.push(0x3000);
const results = new Map();
let runs=0;
for (let i=0;i<cps.length;i+=2){
  const a=cps[i], b=cps[i+1];
  const sa='z'+String.fromCodePoint(a);
  const sb=(b===undefined)?'z':'z'+String.fromCodePoint(b);
  const r=spawnSync(EXE,['--a','x','--b','x','--c',sa,'--d',sb],{encoding:'latin1'});
  runs++;
  const L=(r.stdout||'').split('\n');
  results.set(a,{rc:r.status, line:L[2]||'', which:'c'});
  if(b!==undefined) results.set(b,{rc:r.status, line:L[3]||'', which:'d'});
}
const stripped=[], errored=[], decoded=[];
for(const cp of cps){
  const v=results.get(cp);
  if(v.line==="b'9'") stripped.push(cp);
  else if(v.line==='' ) errored.push(cp);
  else decoded.push(cp);
}
console.log('total codepoints tested:',cps.length,'runs:',runs);
console.log('STRIPPED ('+stripped.length+'):', stripped.map(hex).join(' '));
console.log('DECODED-as-base58-char ('+decoded.length+'):', decoded.map(hex).join(' '));
console.log('ERROR/exit1 count:', errored.length);
// dump raw for stripped + a few
console.log('--- raw lines for STRIPPED ---');
for(const cp of stripped) console.log(hex(cp), 'rc='+results.get(cp).rc, 'arg='+results.get(cp).which, JSON.stringify(results.get(cp).line));
EOF
