cat > /tmp/sweep3.js <<'EOF'
const {spawnSync}=require('child_process');
const EXE='/workspace/dataset/test15_executable';
const hex=cp=>'U+'+cp.toString(16).toUpperCase().padStart(4,'0');
let cands=JSON.parse(require('fs').readFileSync('/tmp/cands.json','utf8')).filter(c=>c!==0);
// deterministic pseudo-random control sample of NON-candidate code points
const cs=new Set(cands); let seed=12345;
const rnd=()=>((seed=(seed*1103515245+12345)&0x7fffffff)/0x7fffffff);
const ctrl=[];
while(ctrl.length<250){const cp=Math.floor(rnd()*0x110000);
  if(cp<1||(cp>=0xD800&&cp<=0xDFFF)||cs.has(cp))continue; ctrl.push(cp);}
const all=cands.concat(ctrl);
const stripped=[],ok=[],e1=[],weird=[];
for(const cp of all){
  const r=spawnSync(EXE,['--a','x','--b','x','--c','z'+String.fromCodePoint(cp),'--d','1'],{encoding:'latin1'});
  const l3=((r.stdout||'').split('\n')[2])||'';
  if(r.status===0&&l3==="b'9'") stripped.push(cp);
  else if(r.status===0) ok.push(cp);
  else if(r.status===1) e1.push(cp);
  else weird.push([cp,r.status]);
}
console.log('tested:',all.length,'(candidates',cands.length,'+ controls',ctrl.length,')');
console.log('STRIPPED ('+stripped.length+'): '+stripped.map(hex).join(' '));
console.log('exit0-not-stripped ('+ok.length+'): '+ok.map(hex).join(' '));
console.log('exit1:',e1.length,' weird:',JSON.stringify(weird));
const strippedInControls=stripped.filter(c=>!cs.has(c));
console.log('stripped code points found in CONTROL sample:',strippedInControls.map(hex).join(' ')||'(none)');
EOF
